import pandas as pd
import re
import random

def task_func(data_list, seed=None):
    rng = random.Random(seed)

    original_strings = []
    modified_strings = []

    for item in data_list:
        original = "" if item is None else str(item)
        original_strings.append(original)

        parts = original.split(",")

        if len(parts) <= 1:
            modified = ""
        else:
            remove_idx = rng.randrange(len(parts))
            modified = ",".join(part for i, part in enumerate(parts) if i != remove_idx)

        modified_strings.append(modified)

    return pd.DataFrame(
        {
            "Original String": original_strings,
            "Modified String": modified_strings,
        }
    )
